import {sortBranches,formatDuration} from './report-utils.js?v=comparison-1';
import {api,initBackend} from './backend.js';
import {downloadReports} from './export.js';
const $=s=>document.querySelector(s),app=$('#app');
let user=null,tab='overview',catalog={branches:[],questions:[]},management=null,reports=null,branchId='',requestKey=crypto.randomUUID(),dirty=false,busy=false;
let inspectionStart=null,branchSort='score-desc',issuesPage=0,reportsPage=0,comparison=null,balancedComparison=false,comparisonCriteria=[],comparisonRequest=0;
const currentMonth=()=>String(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Tbilisi',month:'numeric'}).format(new Date())).padStart(2,'0');
let filter={from:'',to:'',branch:'',month:currentMonth()}; let monitoringFilter='all',timeSort='desc',monitoringReportSort='penalty-desc',monitoringReportCriterion=''; let supervisorTimeReport={rows:[]},monitoringReport={rows:[],criteria:[]}; const monitoringState={catalog:{branches:[],criteria:[]},issues:{rows:[],total:0},time:{rows:[]},notifications:[],weekly:{rows:[],summary:{}},leave:[]};
const labels=['კრიტიკული','ცუდი','საშუალო','კარგი','შესანიშნავი'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Intl.DateTimeFormat('ka-GE',{timeZone:'Asia/Tbilisi',dateStyle:'medium',timeStyle:'short',hourCycle:'h23'}).format(new Date(s));
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',6000)}
const brand=()=>'<div class="brand">ობიექტების მონიტორინგი</div>';
function login(){app.innerHTML=`<main class="login"><section class="login-story">${brand()}<div><h1>ქსელის მართვის სისტემა</h1></div><div class="story-bottom">ობიექტების შემოწმება · შეფასება · ანალიტიკა</div></section><section class="login-form"><div class="login-box"><div class="eyebrow">მოგესალმებით</div><h2>სისტემაში შესვლა</h2><p class="muted">შეიყვანეთ თქვენი მომხმარებლის სახელი და პაროლი.</p><form id="login-form"><div class="field"><label for="username">მომხმარებლის სახელი</label><input id="username" name="username" autocomplete="username" required maxlength="64" autofocus></div><div class="field"><label for="password">პაროლი</label><input id="password" name="password" type="password" autocomplete="current-password" required maxlength="128"></div><div id="login-error" class="error-text" role="alert"></div><button class="btn">შესვლა <span>→</span></button></form><p class="login-note">წვდომისთვის მიმართეთ ადმინისტრატორს. ანგარიშების საჯარო რეგისტრაცია დახურულია.</p></div></section></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{user=await api('/api/login','POST',Object.fromEntries(new FormData(e.target)));tab=user.role==='monitoring'?'monitoring-issues':'overview';await load()}catch(err){$('#login-error')&&($('#login-error').textContent=err.message)}finally{btn.disabled=false}}}
const navs=[['overview','◫','მიმოხილვა'],['inspection','＋','ახალი შემოწმება'],['branches','⌘','ფილიალები'],['questions','☷','კრიტერიუმები'],['users','♙','მომხმარებლები'],['monitoring-criteria','☷','მონიტორინგის საკითხების კრიტერიუმები'],['monitoring-issues','!','მონიტორინგის საკითხები'],['new-issue','＋','საკითხის დაფიქსირება'],['supervisor-time','◷','ვაიზერის ფილიალში გატარებული დრო'],['weekly','◷','კვირის გეგმა'],['vacation','☼','შვებულება'],['notifications','◉','შეტყობინებები'],['profile','♙','პროფილი']];
function shell(content){app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">სამუშაო სივრცე</div><nav class="nav" aria-label="მთავარი მენიუ">${navs.filter(n=>{const allowed=user.role==='admin'?['overview','branches','questions','users','monitoring-criteria','monitoring-issues','weekly','vacation','notifications']:user.role==='monitoring'?['monitoring-issues','new-issue','supervisor-time','notifications','profile']:['overview','inspection','monitoring-issues','weekly','vacation','notifications','profile'];return allowed.includes(n[0])}).map(n=>`<button data-tab="${n[0]}" class="${tab===n[0]?'active':''}" ${tab===n[0]?'aria-current="page"':''}><span class="symbol" aria-hidden="true">${n[1]}</span>${n[2]}</button>`).join('')}</nav><div class="side-bottom"><span class="pill"><span class="badge-dot"></span> სამუშაო სივრცე</span></div></aside><div><header class="topbar"><small>ქსელის მართვის სისტემა</small><div class="user"><span class="avatar">${esc(user.name[0])}</span><div><div class="user-name">${esc(user.name)}</div><small>${user.role==='admin'?'ადმინისტრატორი':user.role==='monitoring'?'მონიტორინგი':'ვაიზერი'}</small></div><button id="logout" class="logout">გასვლა ↗</button></div></header><main class="content">${content}</main></div></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=async()=>{if(dirty&&!confirm('შეუნახავი პასუხები დაიკარგება. გსურთ გვერდის შეცვლა?'))return;dirty=false;tab=b.dataset.tab;await safely(load)});$('#logout').onclick=async()=>{if(dirty&&!confirm('შეუნახავი პასუხები დაიკარგება. გამოხვიდეთ?'))return;await safely(async()=>{await api('/api/logout','POST',{});user=null;dirty=false;login()})}}
async function safely(fn){try{await fn()}catch(e){toast(e.message,true)}}
function heading(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">ობიექტების მონიტორინგი / ${user.role==='admin'?'მართვის პანელი':'სამუშაო სივრცე'}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function monthRange(month){if(!month)return{};const y=new Date().toLocaleString('en-US',{timeZone:'Asia/Tbilisi',year:'numeric'});const m=String(month).padStart(2,'0');const next=Number(m)===12?`${Number(y)+1}-01-01`:`${y}-${String(Number(m)+1).padStart(2,'0')}-01`;return {from:`${y}-${m}-01`,to:new Date(`${next}T00:00:00Z`).toISOString().slice(0,10)} }
const qs=()=>{const f=filter.month?{...filter,...monthRange(filter.month)}:filter;return new URLSearchParams(Object.fromEntries([...Object.entries(f),['page',reportsPage],['page_size',5]].filter(([,v])=>v))).toString()};
async function load(){if(!user)return;if(tab==='monitoring-criteria'){monitoringState.catalog.criteria=await api('/api/admin/monitoring/criteria');renderMonitoringCriteria();return}if(tab==='profile'){renderProfile();return}if(tab==='weekly'){monitoringState.weekly=await api('/api/compliance/weekly');renderWeekly();return}if(tab==='vacation'){monitoringState.leave=await api('/api/compliance/leave');renderLeave();return}if(['monitoring-issues','new-issue','supervisor-time','notifications'].includes(tab)){await loadMonitoring();return}catalog=await api('/api/catalog');if(['overview','reports'].includes(tab)){management=await api('/api/analysis/catalog');reports=await api('/api/reports?'+qs());if(tab==='overview'){await fetchComparison();if(user.role==='admin'){const q=qs();supervisorTimeReport=await api('/api/supervisor-time/report?'+q+'&sort='+encodeURIComponent(timeSort));monitoringReport=await api('/api/monitoring-report?'+q+'&sort='+encodeURIComponent(monitoringReportSort)+(monitoringReportCriterion?'&criterion='+monitoringReportCriterion:''))}}renderReports()}else if(tab==='inspection')renderInspection();else{management=await api('/api/admin/catalog');renderManagement()}}
function filters(){const bs=management?.branches||catalog.branches;const months=['იანვარი','თებერვალი','მარტი','აპრილი','მაისი','ივნისი','ივლისი','აგვისტო','სექტემბერი','ოქტომბერი','ნოემბერი','დეკემბერი'];return `<form id="filter-form" class="filters overview-filters"><div class="field"><label for="from">თარიღიდან</label><input id="from" type="date" name="from" value="${esc(filter.from)}"></div><div class="field"><label for="to">თარიღამდე</label><input id="to" type="date" name="to" value="${esc(filter.to)}"></div><div class="field"><label for="month">თვე</label><select id="month" name="month"><option value="">ყველა თვე</option>${months.map((m,i)=>`<option value="${String(i+1).padStart(2,'0')}" ${filter.month===String(i+1).padStart(2,'0')?'selected':''}>${m}</option>`).join('')}</select></div><div class="field"><label for="branch">ფილიალი</label><select id="branch" name="branch"><option value="">ყველა ფილიალი</option>${bs.map(b=>`<option value="${b.id}" ${filter.branch===String(b.id)?'selected':''}>${esc(b.name)}${b.active?'':' (არქივი)'}</option>`).join('')}</select></div><button class="btn filter-action">გაფილტვრა</button></form>`}
function score(n){return `<span class="score ${n<=2?'bad':''}">${n??'—'} / 5</span>`}
function reportTable(){const pages=Math.max(1,Math.ceil((reports.total||0)/5));return reports.rows.length?`<div class="table-wrap"><table><thead><tr><th>№</th><th>ფილიალი</th><th>ვაიზერი</th><th>თარიღი</th><th>შეფასება</th><th></th></tr></thead><tbody>${reports.rows.map(r=>`<tr><td><strong>#${r.id}</strong></td><td><strong>${esc(r.branch_name)}</strong><br><small>${r.answer_count} კრიტერიუმი</small></td><td>${esc(r.user_name)}</td><td>${date(r.created_at)}${user.role==='admin'?`<br><small>დაწყება: ${r.started_at?date(r.started_at):'—'}<br>ხანგრძლივობა: ${formatDuration(r.duration_seconds)}</small>`:''}</td><td>${score(r.score)}</td><td><div class="actions"><button class="btn secondary small" data-report="${r.id}">ნახვა ↗</button>${user.role==='admin'?`<button class="btn secondary small" data-edit-report="${r.id}">რედაქტირება</button><button class="btn danger small" data-delete-report="${r.id}" data-revision="${r.revision}">წაშლა</button>`:''}</div></td></tr>`).join('')}</tbody></table></div><div class="pagination"><small>გვერდი ${reportsPage+1} / ${pages} · ${reports.total||0} ჩანაწერი</small><div class="actions"><button class="btn secondary small" id="reports-prev" ${reportsPage<=0?'disabled':''}>წინა</button><button class="btn secondary small" id="reports-next" ${reportsPage>=pages-1?'disabled':''}>შემდეგი</button></div></div>`:'<div class="empty"><strong>შემოწმებები ჯერ არ არის</strong>დაამატეთ ფილიალები და კრიტერიუმები, შემდეგ შეავსეთ პირველი შემოწმება.<br>თუ ფილტრს იყენებთ, სცადეთ სხვა პერიოდი.</div>'}
function periodSnapshotLabel(d){return d?new Intl.DateTimeFormat('ka-GE',{timeZone:'Asia/Tbilisi',dateStyle:'medium'}).format(new Date(d+'T12:00:00')):'—'}
function periodNumber(n){return n==null?'—':Number(n).toFixed(2)}
function periodChart(metric,start,end,type){
 const values=[Number(start?.[metric]||0),Number(end?.[metric]||0)],max=Math.max(...values,metric==='final_score'?5:1),labels=[periodSnapshotLabel(start?.date),periodSnapshotLabel(end?.date)],title=metric==='final_score'?'საბოლოო რეიტინგი':'Monitoring საკითხები',color=metric==='final_score'?'#4477cc':'#d8893d';
 if(type==='line'){const y=v=>metric==='final_score'?180-(v/5)*125:180-(v/(max||1))*125;return '<div class="period-chart"><h3>'+title+'</h3><svg viewBox="0 0 560 220" role="img" aria-label="'+title+' ორ თარიღზე"><line x1="70" y1="180" x2="510" y2="180" stroke="currentColor" opacity=".25"/><line x1="70" y1="35" x2="70" y2="180" stroke="currentColor" opacity=".25"/><polyline fill="none" stroke="'+color+'" stroke-width="4" points="150,'+y(values[0])+' 430,'+y(values[1])+'"/><circle cx="150" cy="'+y(values[0])+'" r="7" fill="'+color+'"/><circle cx="430" cy="'+y(values[1])+'" r="7" fill="'+color+'"/><text x="150" y="205" text-anchor="middle">'+labels[0]+'</text><text x="430" y="205" text-anchor="middle">'+labels[1]+'</text><text x="42" y="'+(y(values[0])+4)+'" text-anchor="end">'+periodNumber(values[0])+'</text><text x="472" y="'+(y(values[1])+4)+'">'+periodNumber(values[1])+'</text></svg></div>'}
 const bar=(x,v)=>'<rect x="'+x+'" y="'+(180-(v/(max||1))*125)+'" width="90" height="'+(v/(max||1))*125+'" rx="4" fill="'+color+'" opacity=".85"/>';
 return '<div class="period-chart"><h3>'+title+'</h3><svg viewBox="0 0 560 220" role="img" aria-label="'+title+' ორ თარიღზე"><line x1="70" y1="180" x2="510" y2="180" stroke="currentColor" opacity=".25"/><line x1="70" y1="35" x2="70" y2="180" stroke="currentColor" opacity=".25"/>'+bar(105,values[0])+bar(365,values[1])+'<text x="150" y="205" text-anchor="middle">'+labels[0]+'</text><text x="410" y="205" text-anchor="middle">'+labels[1]+'</text><text x="150" y="'+(175-(values[0]/(max||1))*125)+'" text-anchor="middle">'+periodNumber(values[0])+'</text><text x="410" y="'+(175-(values[1]/(max||1))*125)+'" text-anchor="middle">'+periodNumber(values[1])+'</text></svg></div>'
}
function periodComparisonSection(){
 if(user.role!=='admin')return '';
 const bs=(management?.branches||[]).filter(b=>b.active),has=periodComparison&&periodComparison.start&&periodComparison.end,s=periodComparison?.start||{},e=periodComparison?.end||{},d=periodComparison?.delta||{};
 const branchOptions=bs.map(b=>'<option value="'+b.id+'" '+(periodBranches.includes(String(b.id))?'selected':'')+'>'+esc(b.name)+'</option>').join('');
 const controls='<form id="period-comparison-form" class="filters"><div class="field"><label for="period-start">საწყისი თარიღი</label><input id="period-start" name="start" type="date" value="'+esc(periodStart)+'" required></div><div class="field"><label for="period-end">საბოლოო თარიღი</label><input id="period-end" name="end" type="date" value="'+esc(periodEnd)+'" required></div><div class="field"><label for="period-branches">ფილიალები</label><select id="period-branches" name="branches" multiple size="3">'+branchOptions+'</select><small>არჩევის გარეშე — ყველა ფილიალი</small></div><button class="btn">შედარება</button><button class="btn secondary" type="button" id="period-chart-toggle">'+(periodChartType==='bar'?'მრუდის ნახვა':'სვეტოვანი ნახვა')+'</button></form>';
 if(!has)return '<section class="card"><div class="card-head"><h2>ორი თარიღის ანალიზი</h2></div><div class="card-body">'+controls+'<p class="muted">აირჩიეთ საწყისი და საბოლოო თარიღები, რომ შედარება გამოჩნდეს.</p></div></section>';
 const scoreDelta=d.score_points==null?'—':(d.score_points>=0?'+':'')+Number(d.score_points).toFixed(2),scorePercent=d.score_percent==null?'—':(d.score_percent>=0?'+':'')+Number(d.score_percent).toFixed(1)+'%',issueDelta=d.issue_points==null?'—':(d.issue_points>=0?'+':'')+d.issue_points,issuePercent=d.issue_percent==null?'—':(d.issue_percent>=0?'+':'')+Number(d.issue_percent).toFixed(1)+'%';
 return '<section class="card"><div class="card-head"><h2>ორი თარიღის ანალიზი</h2></div><div class="card-body">'+controls+'<div class="stats"><div class="stat"><div class="stat-label">რეიტინგის ცვლილება</div><strong>'+scoreDelta+'</strong><small>'+scorePercent+'</small></div><div class="stat"><div class="stat-label">Monitoring საკითხების ცვლილება</div><strong>'+issueDelta+'</strong><small>'+issuePercent+'</small></div></div><div class="period-charts">'+periodChart('final_score',s,e,periodChartType)+periodChart('monitoring_issues',s,e,periodChartType)+'</div></div></section>'
}

function supervisorTimeReportSection(){if(user.role!=='admin')return '';const rows=(supervisorTimeReport.rows||[]).map(r=>`<tr><td><strong>#${r.last_record_id||'—'}</strong></td><td><strong>${esc(r.branch_name)}</strong><br><small>${esc(r.supervisor_name||'—')}</small></td><td>${r.records}</td><td><strong>${formatDuration(r.total_seconds)}</strong></td><td>${r.last_record_at?date(r.last_record_at):'—'}</td></tr>`).join('');return `<section class="card"><div class="card-head"><h2>ვაიზერის ფილიალში გატარებული დრო</h2><div class="field inline-field"><label for="time-sort">დალაგება</label><select id="time-sort"><option value="desc" ${timeSort==='desc'?'selected':''}>დიდიდან პატარისკენ</option><option value="asc" ${timeSort==='asc'?'selected':''}>პატარიდან დიდისკენ</option></select></div></div>${rows?`<div class="table-wrap"><table><thead><tr><th>№</th><th>ფილიალი / ვაიზერი</th><th>ჩანაწერები</th><th>სულ დრო</th><th>ბოლო ჩანაწერი</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty">არჩეულ პერიოდში დროის ჩანაწერები არ არის.</div>'}</section>`}
function monitoringIssueReportSection(){if(user.role!=='admin')return '';const rows=(monitoringReport.rows||[]).map(r=>`<tr><td><strong>${esc(r.branch_name)}</strong></td><td><strong>${Number(r.penalty_sum||0).toFixed(2)}</strong></td><td>${r.issue_count}</td><td>${r.open_count} ღია · ${r.closed_count} დახურული</td></tr>`).join('');const criteria=(monitoringReport.criteria||[]).filter(c=>c.active);return `<section class="card"><div class="card-head"><h2>მონიტორინგის საკითხების რეპორტი</h2><div class="actions"><div class="field inline-field"><label for="monitoring-report-criterion">კრიტერიუმი</label><select id="monitoring-report-criterion"><option value="">ყველა</option>${criteria.map(c=>`<option value="${c.id}" ${monitoringReportCriterion===String(c.id)?'selected':''}>${esc(c.title)}</option>`).join('')}</select></div><div class="field inline-field"><label for="monitoring-report-sort">დალაგება</label><select id="monitoring-report-sort"><option value="penalty-desc" ${monitoringReportSort==='penalty-desc'?'selected':''}>ჯარიმა: დიდი-პატარა</option><option value="penalty-asc" ${monitoringReportSort==='penalty-asc'?'selected':''}>ჯარიმა: პატარა-დიდი</option><option value="count-desc" ${monitoringReportSort==='count-desc'?'selected':''}>საკითხები: ბევრი-ცოტა</option><option value="count-asc" ${monitoringReportSort==='count-asc'?'selected':''}>საკითხები: ცოტა-ბევრი</option></select></div></div></div>${rows?`<div class="table-wrap"><table><thead><tr><th>ფილიალი</th><th>ჯარიმის ჯამი</th><th>საკითხების რაოდენობა</th><th>სტატუსები</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty">არჩეულ პერიოდში მონიტორინგის საკითხები არ არის.</div>'}</section>`}
function renderReports(){const r=reports,overview=tab==='overview';const comparisonSection=overview?'<section class="card"><div class="card-head"><h2>ფილიალების მდგომარეობა</h2>'+comparisonControls()+'</div><div class="card-body">'+comparisonBody()+'</div></section>':'';shell(heading(overview?'ქსელის მიმოხილვა':'შემოწმების ანგარიშები',overview?'თქვენი ფილიალების მდგომარეობა — ერთ სივრცეში.':'ნახეთ შემოწმებების ისტორია და ჩამოტვირთეთ მონაცემები.', '<div class="actions">'+(user.role==='admin'?'<button class="btn secondary small" id="deleted-reports">წაშლილი შემოწმებები</button><button class="btn" id="new-inspection">＋ ახალი შემოწმება</button><button class="btn secondary" id="export">↓ Excel ექსპორტი</button>':'')+'</div>')+'<div class="stats"><div class="stat"><span class="stat-icon">▤</span><div class="stat-label">სულ შემოწმება</div><strong>'+r.total+'</strong><small>არჩეულ პერიოდში</small></div><div class="stat"><span class="stat-icon">☆</span><div class="stat-label">ქსელის საშუალო შეფასება</div><strong>'+(r.stats.score??'—')+'</strong><small>5 ქულიდან</small></div><button type="button" class="stat issue-stat" id="show-issues" aria-label="საყურადღებო პასუხების ნახვა"><span class="stat-icon">!</span><div class="stat-label">საყურადღებო პასუხები</div><strong>'+(r.stats.issues||0)+'</strong><small>შეფასება 1 ან 2 · ნახვა →</small></button></div><section class="card"><div class="card-body">'+filters()+'</div></section><section class="card"><div class="card-head"><h2>შემოწმებების ისტორია</h2><small>'+r.total+' ჩანაწერი · ნაჩვენებია 5 თითო გვერდზე</small></div>'+reportTable()+'</section>'+comparisonSection+(overview&&user.role==='admin'?supervisorTimeReportSection()+monitoringIssueReportSection():'') );$('#show-issues').onclick=()=>{issuesPage=0;safely(showIssues)};if(overview)bindComparison();$('#filter-form').onsubmit=async e=>{e.preventDefault();filter=Object.fromEntries(new FormData(e.target));reportsPage=0;await safely(load)};if($('#reports-prev'))$('#reports-prev').onclick=()=>{reportsPage=Math.max(0,reportsPage-1);safely(load)};if($('#reports-next'))$('#reports-next').onclick=()=>{reportsPage++;safely(load)};if($('#deleted-reports'))$('#deleted-reports').onclick=()=>safely(showDeletedReports);if($('#new-inspection'))$('#new-inspection').onclick=()=>{tab='inspection';renderInspection()};if($('#export'))$('#export').onclick=()=>safely(async()=>{downloadReports(await api('/api/export?'+qs()))});if($('#time-sort'))$('#time-sort').onchange=e=>{timeSort=e.target.value;safely(load)};if($('#monitoring-report-sort'))$('#monitoring-report-sort').onchange=e=>{monitoringReportSort=e.target.value;safely(load)};if($('#monitoring-report-criterion'))$('#monitoring-report-criterion').onchange=e=>{monitoringReportCriterion=e.target.value;safely(load)};document.querySelectorAll('[data-edit-report]').forEach(b=>b.onclick=()=>safely(()=>editReport(b.dataset.editReport)));document.querySelectorAll('[data-delete-report]').forEach(b=>b.onclick=()=>safely(async()=>{if(!confirm('წაიშალოს შემოწმება #'+b.dataset.deleteReport+'? ის აღარ გამოჩნდება ანგარიშებსა და ანალიტიკაში. აღდგენა შესაძლებელია წაშლილი შემოწმებებიდან.'))return;b.disabled=true;try{await api('/api/reports/'+b.dataset.deleteReport+'/delete','POST',{revision:Number(b.dataset.revision)});toast('შემოწმება წაიშალა');await load()}finally{b.disabled=false}}));document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>safely(()=>showReport(b.dataset.report)))}
async function startInspection(){const key=requestKey;const r=await api('/api/inspections/start','POST',{branch_id:Number(branchId),request_key:key});if(key===requestKey){inspectionStart=r.started_at;const el=$('#inspection-timing');if(el)el.textContent='დაწყება: '+date(inspectionStart)+' · დასრულება დაფიქსირდება შენახვისას.'}}
async function showReport(id){const r=await api('/api/reports/'+id);const d=$('#detail');d.innerHTML=`<div class="card-head"><div><h2>${esc(r.branch_name)}</h2><small>#${r.id} · ${date(r.created_at)} · ${esc(r.user_name)}</small></div><button class="btn secondary small" id="close-detail">დახურვა</button></div>${r.answers.map(a=>`<div class="detail-row"><span>${esc(a.question_text)}</span>${score(a.rating)}</div>`).join('')}${user.role==='admin'?`<div class="timing-summary"><p>დაწყება: ${r.started_at?date(r.started_at):'ძველ ჩანაწერში არ აღირიცხებოდა'}</p><p>დასრულება: ${date(r.created_at)}</p><p>ხანგრძლივობა: ${formatDuration(r.duration_seconds)}</p></div>`:''}<h3>კომენტარი</h3><p class="muted">${esc(r.note||'კომენტარი არ არის')}</p>`;$('#close-detail').onclick=()=>d.close();d.showModal()}function renderInspection(){const questions=catalog.questions.filter(q=>q.branch_id===null||q.branch_id===Number(branchId));shell(heading('ახალი შემოწმება','აირჩიეთ ფილიალი და შეაფასეთ თითოეული სავალდებულო პუნქტი.',`<span class="pill"><span class="badge-dot"></span> ყველა პასუხი სავალდებულოა</span>`)+`<div class="section-grid"><div><section class="card"><div class="card-head"><h2>01 / ფილიალის არჩევა</h2></div><div class="card-body"><label for="inspection-branch">რომელ ფილიალს ამოწმებთ?</label><select id="inspection-branch"><option value="">აირჩიეთ ფილიალი</option>${catalog.branches.map(b=>`<option value="${b.id}" ${String(b.id)===branchId?'selected':''}>${esc(b.name)}</option>`).join('')}</select>${!catalog.branches.length?'<p class="muted">ადმინისტრატორმა ჯერ უნდა დაამატოს ფილიალები.</p>':''}</div></section><section class="card"><div class="card-head"><h2>02 / მდგომარეობის შეფასება</h2><small id="progress-label">0 / ${branchId?questions.length:0} შევსებული</small></div><div class="card-body">${!branchId?'<div class="empty">კრიტერიუმების სანახავად აირჩიეთ ფილიალი.</div>':!questions.length?'<div class="empty">ამ ფილიალს კრიტერიუმები ჯერ არ აქვს.<br>მიმართეთ ადმინისტრატორს.</div>':`<form id="inspection-form">${user.role==='admin'?`<p class="muted" id="inspection-timing">${inspectionStart?'დაწყება: '+date(inspectionStart):'დაწყების დრო ფიქსირდება…'}</p>`:''}${questions.map((q,i)=>`<fieldset class="question"><legend><span class="q-number">${String(i+1).padStart(2,'0')}</span>${esc(q.text)} *</legend><div class="ratings">${labels.map((l,j)=>`<label class="rating"><input type="radio" name="q${q.id}" value="${j+1}" required><span><b>${j+1}</b>${l}</span></label>`).join('')}</div></fieldset>`).join('')}<div class="progress-bar"><div id="inspection-progress" class="progress-fill" data-step="0"></div></div><div class="field note-field"><label for="note">დამატებითი კომენტარი <small>არასავალდებულო</small></label><textarea id="note" name="note" maxlength="2000" placeholder="რა საჭიროებს ყურადღებას?"></textarea></div><div id="inspection-error" class="error-text" role="alert"></div><div class="inspection-footer">${user.role==='admin'?'<small>შენახვისას დაფიქსირდება დრო და თქვენი სახელი.</small>':''}<button class="btn" id="save-inspection">✓ შემოწმების შენახვა</button></div></form>`}</div></section></div><aside><section class="card"><div class="card-head"><h2>შეფასების გზამკვლევი</h2></div><div class="card-body"><p class="muted">შეაფასეთ ობიექტის რეალური მდგომარეობა ვიზიტის მომენტში.</p><ul class="scale-list">${labels.map((l,i)=>`<li><b>${i+1}</b>${l}</li>`).join('')}</ul><div class="hint"><h3>ყურადღება დეტალებს</h3>დაბალი შეფასების შემთხვევაში კომენტარში აღწერეთ პრობლემა და სასურველი გამოსწორება.</div></div></section><p class="muted">თარიღი და დრო ინახება ავტომატურად. ანგარიშებში დრო ნაჩვენებია თბილისის დროით.</p></aside></div>`);
 $('#inspection-branch').onchange=e=>{if(dirty&&!confirm('ფილიალის შეცვლისას პასუხები დაიკარგება. გაგრძელდეს?')){e.target.value=branchId;return}branchId=e.target.value;dirty=false;requestKey=crypto.randomUUID();inspectionStart=null;renderInspection();if(branchId)safely(startInspection)};const form=$('#inspection-form');if(form){form.oninput=()=>{dirty=true;const count=new Set([...form.querySelectorAll('input:checked')].map(el=>el.name)).size;$('#progress-label').textContent=count+' / '+questions.length+' შევსებული';$('#inspection-progress').dataset.step=String(Math.floor(count/questions.length*5))};form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('#save-inspection').disabled=true;const fd=new FormData(form);try{if(!inspectionStart)await startInspection();const result=await api('/api/inspections','POST',{branch_id:Number(branchId),request_key:requestKey,note:fd.get('note'),answers:questions.map(q=>({question_id:q.id,question_text:q.text,rating:Number(fd.get('q'+q.id))}))});dirty=false;requestKey=crypto.randomUUID();shell(heading('შემოწმება დასრულებულია','ჩანაწერი წარმატებით შეინახა.')+`<section class="card success-panel"><div class="success-icon">✓</div><h2>მადლობა, ${esc(user.name)}!</h2><p>შემოწმება #${result.id} შენახულია.<br>ფილიალი: ${esc(catalog.branches.find(b=>String(b.id)===branchId)?.name)}</p><button class="btn" id="another">＋ ახალი შემოწმება</button></section>`);inspectionStart=null;branchId='';$('#another').onclick=()=>{branchId='';inspectionStart=null;renderInspection()}}catch(err){$('#inspection-error')&&($('#inspection-error').textContent=err.message);$('#save-inspection')&&($('#save-inspection').disabled=false)}finally{busy=false}}}}

function branchSupervisorName(i){const p=(management?.users||[]).find(u=>String(u.id)===String(i.supervisor_user_id));return i.supervisor_name||p?.name||'ვაიზერი არ არის მიმაგრებული'}
function assignBranchDialog(i){
 const d=$('#detail'),users=(management.users||[]).filter(u=>u.role==='inspector'&&u.active);
 d.innerHTML='<h2>ვაიზერის შეცვლა</h2><form id="branch-assignment-form"><div class="field"><label for="branch-supervisor">ვაიზერი</label><select id="branch-supervisor" name="supervisor_user_id" required>'+users.map(u=>'<option value="'+u.id+'" '+(String(u.id)===String(i.supervisor_user_id)?'selected':'')+'>'+esc(u.name)+'</option>').join('')+'</select></div><div class="error-text" id="branch-assignment-error" role="alert"></div><div class="actions"><button class="btn">შენახვა</button><button class="btn secondary" type="button" id="cancel-branch-assignment">გაუქმება</button></div></form>';
 $('#cancel-branch-assignment').onclick=()=>d.close();
 $('#branch-assignment-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/admin/monitoring/branches/'+i.id+'/assignment','PATCH',Object.fromEntries(new FormData(e.target)));d.close();toast('ფილიალის ვაიზერი შეიცვალა — ცვლილება მომავალზე იმოქმედებს');await load()}catch(err){$('#branch-assignment-error').textContent=err.message}finally{b.disabled=false}})};
 d.showModal()
}
function renderManagement(){
 const type=tab,items=management[type];let form='';
 if(type==='branches')form='<div class="field"><label for="name">ფილიალის სახელი</label><input id="name" name="name" required maxlength="200" placeholder="მაგ. ვაკე — ჭავჭავაძის ფილიალი"></div><div class="field"><label for="supervisor_user_id">პასუხისმგებელი ვაიზერი</label><select id="supervisor_user_id" name="supervisor_user_id" required><option value="">აირჩიეთ ვაიზერი</option>'+management.users.filter(u=>u.role==='inspector'&&u.active).map(u=>'<option value="'+u.id+'">'+esc(u.name)+'</option>').join('')+'</select></div>';
 else if(type==='questions')form='<div class="field"><label for="text">კრიტერიუმის დასახელება</label><input id="text" name="text" required maxlength="500" placeholder="მაგ. სავაჭრო დარბაზის სისუფთავე"></div><div class="field"><label for="branch_id">ფილიალი</label><select id="branch_id" name="branch_id"><option value="">ყველა ფილიალი</option>'+management.branches.filter(b=>b.active).map(b=>'<option value="'+b.id+'">'+esc(b.name)+'</option>').join('')+'</select>';
 else form='<div class="field"><label for="name">სახელი და გვარი</label><input id="name" name="name" required maxlength="200"></div><div class="field"><label for="username">მომხმარებლის სახელი</label><input id="username" name="username" required pattern="[a-zA-Z0-9_.-]{3,64}" autocomplete="off"></div><div class="field"><label for="new-password">პაროლი (მინ. 6 სიმბოლო)</label><input id="new-password" name="password" type="password" minlength="6" maxlength="128" autocomplete="new-password" required></div><div class="field"><label for="role">როლი</label><select id="role" name="role"><option value="inspector">ვაიზერი</option><option value="monitoring">მონიტორინგი</option></select></div>';
 const title=navs.find(n=>n[0]===type)[2];
 const head=type==='branches'?'<tr><th>სახელი</th><th>ვაიზერი</th><th>სტატუსი</th><th>მოქმედებები</th></tr>':'<tr><th>'+ (type==='questions'?'კრიტერიუმი':'სახელი')+'</th><th>'+ (type==='questions'?'ფილიალი':type==='users'?'როლი':'სტატუსი')+'</th><th>მოქმედებები</th></tr>';
 const body=items.map(i=>{
   if(type==='branches')return '<tr><td><strong>'+esc(i.name)+'</strong></td><td>'+esc(branchSupervisorName(i))+'</td><td><span class="pill '+(i.active?'':'archived')+'">'+(i.active?'აქტიური':'არქივში')+'</span></td><td><div class="actions"><button class="btn secondary small" data-branch-assign="'+i.id+'">ვაიზერის შეცვლა</button><button class="btn secondary small" data-edit="'+i.id+'">შეცვლა</button><button class="btn '+(i.active?'danger':'secondary')+' small" data-toggle="'+i.id+'">'+(i.active?'არქივში გადატანა':'აღდგენა')+'</button></div></td></tr>';
   return '<tr><td><strong>'+esc(i.text||i.name)+'</strong>'+(type==='users'?'<br><small>'+esc(i.username)+'</small>':'')+(!i.active?'<br><span class="pill archived">არქივში / გამორთული</span>':'')+'</td><td>'+ (type==='questions'?esc(i.branch_name||'ყველა ფილიალი'):type==='users'?(i.role==='admin'?'ადმინისტრატორი':i.role==='monitoring'?'მონიტორინგი':'ვაიზერი'):'<span class="pill '+(i.active?'':'archived')+'">'+(i.active?'აქტიური':'არქივში')+'</span>')+'</td><td><div class="actions"><button class="btn secondary small" data-edit="'+i.id+'">შეცვლა</button>'+ (type==='users'?'<button class="btn secondary small" data-password="'+i.id+'">პაროლი</button>':'')+ (type==='users'&&i.id!==user.id?'<button class="btn secondary small" data-role="'+i.id+'">'+(i.role==='admin'?'ინსპექტორად':'ადმინისტრატორად')+'</button>':'')+((type!=='users'||i.id!==user.id)?'<button class="btn '+(i.active?'danger':'secondary')+' small" data-toggle="'+i.id+'">'+(i.active?(type==='users'?'გათიშვა':'არქივში გადატანა'):'აღდგენა')+'</button>':'')+'</div></td></tr>'
 }).join('');
 shell(heading(title,type==='users'?'მართეთ თანამშრომლების წვდომა და როლები.':'დაამატეთ, შეცვალეთ ან დააარქივეთ ჩანაწერები. ისტორია შენარჩუნდება.')+'<section class="card"><div class="card-head"><h2>'+ (type==='questions'?'კრიტერიუმის დამატება':'ახალი ჩანაწერი')+'</h2></div><div class="card-body"><form id="management-form" class="management-form '+type+'">'+form+'<button class="btn">＋ დამატება</button></form></div></section><section class="card"><div class="card-head"><h2>'+title+'</h2><small>'+items.length+' ჩანაწერი</small></div>'+(items.length?'<div class="table-wrap"><table><thead>'+head+'</thead><tbody>'+body+'</tbody></table></div>':'<div class="empty">ჩანაწერები ჯერ არ არის. დაამატეთ პირველი ჩანაწერი.</div>')+'</section>');
 $('#management-form').onsubmit=e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;safely(async()=>{try{await api('/api/'+type,'POST',Object.fromEntries(new FormData(e.target)));toast('ჩანაწერი დამატებულია');await load()}finally{b.disabled=false}})};
 const update=(id,data)=>safely(async()=>{await api('/api/'+type+'/'+id,'PATCH',data);toast('ცვლილება შენახულია');await load()});
 document.querySelectorAll('[data-branch-assign]').forEach(b=>b.onclick=()=>assignBranchDialog(items.find(i=>String(i.id)===b.dataset.branchAssign)));
 document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const i=items.find(i=>String(i.id)===b.dataset.toggle);if(confirm(i.active?'გსურთ ჩანაწერის გამორთვა? ისტორია შენარჩუნდება.':'გსურთ ჩანაწერის აღდგენა?'))update(i.id,{active:!i.active})});
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const i=items.find(i=>String(i.id)===b.dataset.edit);const key=type==='questions'?'text':'name',v=prompt('შეიყვანეთ ახალი ტექსტი:',i[key]);if(v!==null)update(i.id,{[key]:v})});
 document.querySelectorAll('[data-password]').forEach(b=>b.onclick=()=>passwordDialog(b.dataset.password));
 document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{const i=items.find(i=>String(i.id)===b.dataset.role);if(confirm('გსურთ მომხმარებლის როლის შეცვლა? მონაცემებზე უფლებები დაუყოვნებლივ შეიცვლება.'))update(i.id,{role:i.role==='inspector'?'monitoring':'inspector'})})
}
function passwordDialog(id){const d=$('#detail');d.innerHTML='<h2>პაროლის შეცვლა</h2><form id="reset-form"><div class="field"><label for="reset-password">ახალი პაროლი</label><input id="reset-password" name="password" type="password" required minlength="6" maxlength="128" autocomplete="new-password"></div><p class="muted">პაროლი განახლდება Supabase Auth-ში. სხვა მოწყობილობების სესიები შესაძლოა ტოკენის ვადის ამოწურვამდე მოქმედებდეს.</p><div class="actions"><button class="btn">შენახვა</button><button class="btn secondary" type="button" id="cancel-reset">გაუქმება</button></div></form>';$('#cancel-reset').onclick=()=>d.close();$('#reset-form').onsubmit=e=>{e.preventDefault();safely(async()=>{await api('/api/users/'+id,'PATCH',Object.fromEntries(new FormData(e.target)));d.close();if(id===user.id){user=null;login()}else toast('პაროლი შეცვლილია')})};d.showModal()}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
function configuration(message){app.innerHTML='<main class="login"><section class="login-story">'+brand()+'<div><div class="eyebrow">GITHUB + SUPABASE</div><h1>თქვენი ქსელი.<br>ერთ სივრცეში.</h1><p>ქართულენოვანი შემოწმების სისტემა მონაცემთა ღრუბლოვანი ბაზით და როლებზე დაფუძნებული წვდომით.</p></div><div class="story-bottom">ობიექტების მონიტორინგი · Supabase ვერსია</div></section><section class="login-form"><div class="login-box"><h2>პროექტის დაკავშირება</h2><p class="muted">'+esc(message||'სისტემის გასააქტიურებლად საჭიროა თქვენი Supabase პროექტის დაკავშირება.')+'</p><ol class="setup-steps"><li>Supabase SQL Editor-ში გაუშვით ორივე მიგრაცია რიგითობით.</li><li>გამოაქვეყნეთ manage-users Edge Function.</li><li>config.js-ში ჩაწერეთ Project URL და საჯარო publishable გასაღები.</li><li>შექმენით პირველი ადმინისტრატორი ინსტრუქციის მიხედვით.</li></ol><p class="login-note">პაროლები და service_role გასაღები არ უნდა მოხვდეს GitHub-სა და config.js-ში. სრული ინსტრუქცია პროექტის README.md ფაილშია.</p><button class="btn" id="retry-config">კავშირის შემოწმება ↻</button></div></section></main>';$('#retry-config').onclick=()=>location.reload()}
(async()=>{try{if(!await initBackend()){configuration();return}try{user=await api('/api/me')}catch(e){login();return}tab=user.role==='monitoring'?'monitoring-issues':'overview';await load()}catch(e){configuration(e.message)}})();

async function showIssues(){const r=await api('/api/issues?'+qs()+'&page='+issuesPage);const d=$('#detail');d.innerHTML=`<div class="card-head"><h2>საყურადღებო პასუხები</h2><button class="btn secondary small" id="close-issues">დახურვა</button></div><p class="muted">შეფასება 1 ან 2 · არჩეული პერიოდი და ფილიალი · სულ ${r.total} პასუხი</p>${r.rows.length?'<div class="table-wrap"><table><thead><tr><th>ფილიალი / თარიღი</th><th>კრიტერიუმი</th><th>ქულა</th><th>ვაიზერი / კომენტარი</th><th></th></tr></thead><tbody>'+r.rows.map(a=>`<tr><td>${esc(a.branch_name)}<br><small>${date(a.created_at)}</small></td><td>${esc(a.question_text)}</td><td>${score(a.rating)}</td><td>${esc(a.user_name)}<br><small>${esc(a.note||'—')}</small></td><td><button class="btn secondary small" data-issue-report="${a.inspection_id}">სრული ანგარიში</button></td></tr>`).join('')+'</tbody></table></div>':'<div class="empty">საყურადღებო პასუხები არ მოიძებნა.</div>'}<div class="actions"><button class="btn secondary small" id="issues-prev" ${issuesPage===0?'disabled':''}>წინა</button><span>${issuesPage+1} / ${Math.max(1,Math.ceil(r.total/100))}</span><button class="btn secondary small" id="issues-next" ${(issuesPage+1)*100>=r.total?'disabled':''}>შემდეგი</button></div>`;$('#close-issues').onclick=()=>d.close();$('#issues-prev').onclick=()=>{issuesPage--;safely(showIssues)};$('#issues-next').onclick=()=>{issuesPage++;safely(showIssues)};d.querySelectorAll('[data-issue-report]').forEach(b=>b.onclick=()=>safely(()=>showReport(b.dataset.issueReport)));if(!d.open)d.showModal()}

async function fetchComparison(){const seq=++comparisonRequest;const params=new URLSearchParams(qs());if(comparisonCriteria.length)params.set('criteria',comparisonCriteria.join(','));params.set('balanced',String(balancedComparison));const data=await api('/api/branch-comparison?'+params);if(seq===comparisonRequest)comparison=data;return seq===comparisonRequest}
function comparisonControls(){return `<div class="comparison-controls"><div class="branch-sort"><label for="branch-sort">დალაგება</label><select id="branch-sort">${[['score-desc','შეფასება: საუკეთესოდან უარესისკენ'],['score-asc','შეფასება: უარესიდან საუკეთესოსკენ'],['name','ფილიალის სახელით'],['issues','საყურადღებო პასუხების რაოდენობით']].map(([v,l])=>`<option value="${v}" ${branchSort===v?'selected':''}>${l}</option>`).join('')}</select></div><button class="btn ${balancedComparison?'':'secondary'}" id="balanced-comparison" aria-pressed="${balancedComparison}">ბოლო ყველა შემოწმება</button></div>`}
function comparisonBody(){const r=comparison||{rows:[],common_count:0,branch_count:0};return `<details class="criteria-filter" ${comparisonCriteria.length?'open':''}><summary>კრიტერიუმებით გაფილტვრა · ${comparisonCriteria.length?comparisonCriteria.length+' არჩეული':'ყველა კრიტერიუმი'}</summary><div class="criteria-options"><label><input type="checkbox" id="all-comparison-criteria" ${comparisonCriteria.length?'':'checked'}> ყველა კრიტერიუმი</label>${management.questions.map(q=>`<label><input type="checkbox" data-comparison-criterion="${q.id}" ${comparisonCriteria.includes(String(q.id))?'checked':''}>${esc(q.text)}${q.active?'':' (არქივი)'}${q.branch_name?' · '+esc(q.branch_name):''}</label>`).join('')||'<p class="muted">კრიტერიუმები ჯერ არ არის დამატებული.</p>'}</div></details><p class="muted">${balancedComparison?'თითოეული ფილიალის ბოლო '+r.common_count+' შემოწმება · '+r.branch_count+' ფილიალი · სულ '+r.total_selected+' შემოწმება':'ყველა შემოწმება არჩეული პერიოდის ფარგლებში'}. საბოლოო რეიტინგი ითვალისწინებს Monitoring-ის მოქმედ ჯარიმებს.</p>${r.rows.length?sortBranches(r.rows,branchSort).map(b=>{const issueRows=(b.monitoring_issues||[]).map(i=>`<li>${esc(i.title)} · -${Number(i.penalty||0).toFixed(2)} <small>${date(i.created_at)}</small></li>`).join('');return `<div class="branch-row"><span><strong>${esc(b.branch_name)}</strong><small> · ${b.inspections} შემოწმება · ${b.rated_inspections} შეფასებულია · ${b.issues||0} საყურადღებო პასუხი</small>${issueRows?`<details><summary>Monitoring-ის მიზეზები (${b.monitoring_issues.length})</summary><ul>${issueRows}</ul></details>`:''}</span><strong><small>საწყისი ${b.base_score==null?'—':b.base_score} · ჯარიმა -${Number(b.monitoring_penalty||0).toFixed(2)}</small><br>${b.score==null?'პასუხები არ არის':b.score+' / 5'}</strong>${b.score==null?'':`<div class="progress-bar"><div class="progress-fill" data-step="${Math.round(b.score)}"></div></div>`}</div>`}).join(''):'<p class="muted">არჩეულ პერიოდში შემოწმებები არ არის.</p>'}`}function bindComparison(){const refresh=()=>safely(async()=>{if(await fetchComparison())renderReports()});$('#branch-sort').onchange=e=>{branchSort=e.target.value;renderReports()};$('#balanced-comparison').onclick=()=>{balancedComparison=!balancedComparison;refresh()};$('#all-comparison-criteria').onchange=()=>{comparisonCriteria=[];refresh()};document.querySelectorAll('[data-comparison-criterion]').forEach(el=>el.onchange=()=>{comparisonCriteria=[...document.querySelectorAll('[data-comparison-criterion]:checked')].map(e=>e.dataset.comparisonCriterion);refresh()})}

async function editReport(id){const r=await api('/api/reports/'+id);const d=$('#detail');d.innerHTML=`<h2>შემოწმების რედაქტირება #${r.id}</h2><p>${esc(r.branch_name)} · ${date(r.created_at)} · ${esc(r.user_name)}</p><p class="muted">შეცვალეთ ქულები და კომენტარი. შეფასების თარიღი, დრო და ვაიზერი შენარჩუნდება.</p><form id="edit-report-form">${r.answers.map((a,i)=>`<div class="field"><label for="edit-rating-${i}">${esc(a.question_text)}</label><select id="edit-rating-${i}" name="q${a.question_id}" required>${labels.map((l,j)=>`<option value="${j+1}" ${a.rating===j+1?'selected':''}>${j+1} — ${l}</option>`).join('')}</select></div>`).join('')}<div class="field"><label for="edit-report-note">კომენტარი</label><textarea id="edit-report-note" name="note" maxlength="2000">${esc(r.note)}</textarea></div><div class="error-text" id="edit-report-error" role="alert"></div><div class="actions"><button class="btn" type="submit">შენახვა</button><button class="btn secondary" type="button" id="cancel-report-edit">გაუქმება</button></div></form>`;$('#cancel-report-edit').onclick=()=>d.close();$('#edit-report-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type="submit"]');b.disabled=true;try{const fd=new FormData(e.target);await api('/api/reports/'+id,'PATCH',{revision:r.revision,note:fd.get('note'),answers:r.answers.map(a=>({question_id:a.question_id,rating:Number(fd.get('q'+a.question_id))}))});d.close();toast('ცვლილება შენახულია');await load()}catch(err){$('#edit-report-error').textContent=err.message}finally{b.disabled=false}};if(!d.open)d.showModal()}
async function showDeletedReports(){const rows=await api('/api/deleted-inspections');const d=$('#detail');d.innerHTML=`<div class="card-head"><h2>წაშლილი შემოწმებები</h2><button class="btn secondary small" id="close-deleted">დახურვა</button></div><p class="muted">ნაჩვენებია ბოლო 200 წაშლილი შემოწმება. აღდგენისას ჩანაწერი ანგარიშებსა და ანალიტიკაში დაბრუნდება.</p>${rows.length?rows.map(r=>`<div class="detail-row"><span>#${r.id} · ${esc(r.branch_name)}<br><small>${date(r.created_at)} · ${esc(r.user_name)}</small></span><div class="actions"><button class="btn secondary small" data-restore-report="${r.id}" data-revision="${r.revision}">აღდგენა</button><button class="btn danger small" data-purge-report="${r.id}" data-revision="${r.revision}">სამუდამოდ წაშლა</button></div></div>`).join(''):'<p>წაშლილი შემოწმებები არ არის.</p>'}`;$('#close-deleted').onclick=()=>d.close();d.querySelectorAll('[data-purge-report]').forEach(b=>b.onclick=()=>safely(async()=>{const id=b.dataset.purgeReport;const answer=prompt('შემოწმება #'+id+' სამუდამოდ წაიშლება ბაზიდან პასუხებთან და ცვლილებების ისტორიასთან ერთად. აღდგენა შეუძლებელია. დასადასტურებლად ჩაწერეთ ნომერი: '+id);if(answer===null)return;if(answer.trim()!==id){toast('ნომერი არ ემთხვევა. ჩანაწერი არ წაშლილა.',true);return}b.disabled=true;try{await api('/api/reports/'+id+'/purge','POST',{revision:Number(b.dataset.revision),purge_confirmation:answer.trim()});await showDeletedReports();await load();toast('შემოწმება სამუდამოდ წაშლილია')}finally{b.disabled=false}}));d.querySelectorAll('[data-restore-report]').forEach(b=>b.onclick=()=>safely(async()=>{b.disabled=true;try{await api('/api/reports/'+b.dataset.restoreReport+'/restore','POST',{revision:Number(b.dataset.revision)});await showDeletedReports();await load();toast('შემოწმება აღდგენილია')}finally{b.disabled=false}}));if(!d.open)d.showModal()}


function monitoringStatusLabel(s){return s==='closed'?'დახურული':'ღია'}
function monitoringSeverityLabel(s){return s==='critical'?'კრიტიკული':s==='important'?'მნიშვნელოვანი':'მსუბუქი'}
async function loadMonitoring(){
 if(tab==='notifications'){monitoringState.notifications=await api('/api/notifications');renderNotifications();return}
 if(tab==='new-issue'){monitoringState.catalog=await api('/api/monitoring/catalog');renderNewMonitoringIssue();return}
 if(tab==='supervisor-time'){monitoringState.catalog=await api('/api/monitoring/catalog');monitoringState.time=await api('/api/supervisor-time');renderSupervisorTime();return}
 var query='page=0&page_size=100';if(user.role==='admin'&&monitoringFilter!=='all')query+='&status='+encodeURIComponent(monitoringFilter);
 monitoringState.issues=await api('/api/monitoring/issues?'+query);renderMonitoringIssues()
}
function localInputValue(value){if(!value)return '';const d=new Date(value);const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tbilisi',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(d).reduce((o,p)=>(o[p.type]=p.value,o),{});return `${parts.year}-${parts.month}-${parts.day}T${parts.hour==='24'?'00':parts.hour}:${parts.minute}`}
function localIso(value){return value?new Date(value).toISOString():''}
function renderSupervisorTime(){const rows=(monitoringState.time?.rows||[]).map(t=>`<tr><td><strong>${esc(t.branch_name)}</strong><br><small>${esc(t.supervisor_name||'—')}</small></td><td>${localInputValue(t.entry_at)}</td><td>${t.exit_at?localInputValue(t.exit_at):'<span class="pill">მიმდინარე</span>'}</td><td>${formatDuration(t.duration_seconds)}</td><td><button class="btn secondary small" data-time-edit="${t.id}">რედაქტირება</button></td></tr>`).join('');const branches=monitoringState.catalog?.branches||[];shell(heading('ვაიზერის ფილიალში გატარებული დრო','მიუთითეთ ვაიზერის ფილიალში შესვლისა და გამოსვლის დრო. მონიტორინგს მხოლოდ მიმდინარე დღის ჩანაწერების ნახვა და რედაქტირება შეუძლია.')+`<section class="card"><div class="card-head"><h2>ახალი ჩანაწერი</h2></div><div class="card-body"><form id="supervisor-time-form" class="management-form"><div class="field"><label for="time-branch">ფილიალი</label><select id="time-branch" name="branch_id" required><option value="">აირჩიეთ ფილიალი</option>${branches.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label for="time-entry">შესვლის დრო</label><input id="time-entry" name="entry_at" type="datetime-local" required></div><div class="field"><label for="time-exit">გამოსვლის დრო (არასავალდებულო)</label><input id="time-exit" name="exit_at" type="datetime-local"></div><div class="error-text" id="time-form-error" role="alert"></div><button class="btn">ჩანაწერის შენახვა</button></form></div></section><section class="card"><div class="card-head"><h2>დღევანდელი ჩანაწერები</h2><small>${(monitoringState.time?.rows||[]).length} ჩანაწერი</small></div>${rows?'<div class="table-wrap"><table><thead><tr><th>ფილიალი / ვაიზერი</th><th>შესვლა</th><th>გასვლა</th><th>ხანგრძლივობა</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>':'<div class="empty">დღევანდელი ჩანაწერები ჯერ არ არის.</div>'}</section>`);$('#time-entry').value=localInputValue(new Date().toISOString());$('#supervisor-time-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const b=e.target.querySelector('button');b.disabled=true;try{const fd=new FormData(e.target);await api('/api/supervisor-time','POST',{branch_id:Number(fd.get('branch_id')),entry_at:localIso(fd.get('entry_at')),exit_at:localIso(fd.get('exit_at'))});toast('დროის ჩანაწერი შეინახა');await loadMonitoring()}catch(err){$('#time-form-error').textContent=err.message}finally{b.disabled=false}})};document.querySelectorAll('[data-time-edit]').forEach(b=>b.onclick=()=>{const t=(monitoringState.time.rows||[]).find(x=>String(x.id)===b.dataset.timeEdit);editSupervisorTime(t)})}
function editSupervisorTime(t){const d=$('#detail');d.innerHTML=`<div class="card-head"><h2>დროის ჩანაწერის რედაქტირება</h2><button class="btn secondary small" id="close-time-detail">დახურვა</button></div><form id="edit-supervisor-time-form"><div class="field"><label>შესვლის დრო</label><input name="entry_at" type="datetime-local" value="${localInputValue(t.entry_at)}" required></div><div class="field"><label>გამოსვლის დრო</label><input name="exit_at" type="datetime-local" value="${localInputValue(t.exit_at)}"></div><div class="error-text" id="edit-time-error" role="alert"></div><button class="btn">შენახვა</button></form>`;$('#close-time-detail').onclick=()=>d.close();$('#edit-supervisor-time-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const b=e.target.querySelector('button');b.disabled=true;try{const fd=new FormData(e.target);await api('/api/supervisor-time/'+t.id,'PATCH',{entry_at:localIso(fd.get('entry_at')),exit_at:localIso(fd.get('exit_at'))});d.close();toast('დროის ჩანაწერი განახლდა');await loadMonitoring()}catch(err){$('#edit-time-error').textContent=err.message}finally{b.disabled=false}})};if(!d.open)d.showModal()}
